"use strict";(self.webpackChunkfhsdocs=self.webpackChunkfhsdocs||[]).push([[3864],{3058:e=>{e.exports=JSON.parse('{"version":{"pluginId":"docsMain","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docsMainSidebar":[{"type":"link","label":"Introduction","href":"/docs_main/intro","docId":"intro","unlisted":false},{"type":"link","label":"Cohort Study Designs","href":"/docs_main/fhs_health_exam_timeline","docId":"resources/fhs_health_exam_timeline","unlisted":false},{"type":"link","label":"General Data Types","href":"/docs_main/general_data_types","docId":"resources/general_data_types","unlisted":false},{"type":"link","label":"Variables","href":"/docs_main/new_variables_page","docId":"variables/new_variables_page","unlisted":false},{"type":"category","label":"Digital Data","items":[{"type":"link","label":"Digital Data Overview","href":"/docs_main/digital_data","docId":"fhsdata/digital_data","unlisted":false},{"type":"link","label":"Digital Pen","href":"/docs_main/digital_pen","docId":"fhsdata/digital_data/digital_pen","unlisted":false},{"type":"link","label":"Digital Voice Recording","href":"/docs_main/digital_voice_recording","docId":"fhsdata/digital_data/digital_voice_recording","unlisted":false},{"type":"link","label":"Voice Transcriptions","href":"/docs_main/voice_transcriptions","docId":"fhsdata/digital_data/voice_transcriptions","unlisted":false},{"type":"link","label":"Neuropath Images","href":"/docs_main/neuropath_images","docId":"fhsdata/digital_data/neuropath_images","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Legacy Data Collection/Processing","items":[{"type":"link","label":"Traumatic Brain Injury Retrospective Chart Review","href":"/docs_main/traumatic_brain_injury_retrospective_chart_review","docId":"fhsdata/legacy_data/traumatic_brain_injury_retrospective_chart_review","unlisted":false},{"type":"link","label":"Qualitative Errors in Neuropsychological Exams","href":"/docs_main/qualitative_errors_in_neuropsychological_exams","docId":"fhsdata/legacy_data/qualitative_errors_in_neuropsychological_exams","unlisted":false},{"type":"link","label":"Hand score clock drawing test","href":"/docs_main/hand_score_clock_drawing_test","docId":"fhsdata/legacy_data/hand_score_clock_drawing_test","unlisted":false},{"type":"link","label":"Parkinson\'s Disease","href":"/docs_main/parkinsons_disease","docId":"fhsdata/legacy_data/parkinsons_disease","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","label":"FAQs","href":"/docs_main/faqs","docId":"faqs","unlisted":false},{"type":"link","label":"Github","href":"https://github.com/orgs/FHS-BAP/repositories"}]},"docs":{"faqs":{"id":"faqs","title":"FAQs","description":"An AI-driven search engine for FHS data is currently being worked on by the FHS-BAP Data Core team and is coming in the future. This enginge will allow people to ask a question and information can be pulled dynamically from all the resources that are publicly acessible.","sidebar":"docsMainSidebar"},"fhsdata/brain_autopsy":{"id":"fhsdata/brain_autopsy","title":"Brain Autopsy","description":"Brain autopsy data. This page combines variable and description information from all three curated datasets."},"fhsdata/dementia_review":{"id":"fhsdata/dementia_review","title":"FHS Dementia Review","description":"Dementia review data. This page combines variable and description information from all three curated datasets."},"fhsdata/digital_data":{"id":"fhsdata/digital_data","title":"Digital Data Overview","description":"Sample Size at Different Check-Up Time Points in Digital Data","sidebar":"docsMainSidebar"},"fhsdata/digital_data/digital_pen":{"id":"fhsdata/digital_data/digital_pen","title":"Digital Pen","description":"The video above demonstrates the use of FHS digitial pen data. The FHS collects digital pen recordings of written responses to the neuropsychological test protocol. This includes digital pen data collected from the digital clock-drawing test involving participant manually drawing clocks and the results being graded. This is similar to the traditional, hand-scored test but uses a special pen and paper to record the actual process as a file without a video. The unique digital pen is equipped with a camera sensor that records real-time pen motion by capturing its time-stamped XY coordinate position relative to specialized marked paper. Machine learning algorithms have been developed to calculate meaningful clock scores based on this information, capturing many clock drawing features that may be too subtle for a human researcher to detect.","sidebar":"docsMainSidebar"},"fhsdata/digital_data/digital_voice_recording":{"id":"fhsdata/digital_data/digital_voice_recording","title":"Digital Voice","description":"The above video is a sample of in-clinic digital voice recording for Framingham Heart Study, performed by a research assistant. Using these voice recordings of participant responses to neuropsychological tests is an effective way to detect changes in cognition. Speaking is a cognitively complex task and embedded in the spoken responses are acoustic and linguistic features mapping onto cognitive domains implicated by neuropathological changes. Shifting cognitive capabilities are expressed through vocal responses in subtle ways.","sidebar":"docsMainSidebar"},"fhsdata/digital_data/mri_freesurfer":{"id":"fhsdata/digital_data/mri_freesurfer","title":"MRI FreeSurfer","description":"FHS MRI Brain FreeSurfer Protocol"},"fhsdata/digital_data/mri_pet_scans":{"id":"fhsdata/digital_data/mri_pet_scans","title":"MRI PET Scans","description":"Summary"},"fhsdata/digital_data/neuropath_images":{"id":"fhsdata/digital_data/neuropath_images","title":"Neuropath Images","description":"Figure 1-4. These images are of parts of brain tissue taken from FHS participants who volunteered to donate their brains for research purposes. The neuropath data in the curated dataset comes from the same brains, where neuropathological evaluation of autopsied brains was performed and gross neuropathological findings were recorded. The full images are large .svs files, which are created by digital microscope scanners as zoomable digital images. (Further information coming soon)","sidebar":"docsMainSidebar"},"fhsdata/digital_data/voice_transcriptions":{"id":"fhsdata/digital_data/voice_transcriptions","title":"Voice Transcriptions","description":"Stanford LMDr Voice Transcription Protocol","sidebar":"docsMainSidebar"},"fhsdata/legacy_data/hand_score_clock_drawing_test":{"id":"fhsdata/legacy_data/hand_score_clock_drawing_test","title":"Hand score clock drawing test","description":"The Clock Drawing Test (CDT) is widely used in both research and clinical practice to assess cognitive function, particularly in elderly individuals and those with neurological or psychiatric disorders. It has been found to correlate well with dementia, including Alzheimer\'s disease (AD). The test evaluates various cognitive abilities such as visuoconstructive skills, memory, attention, executive functions, and more. Despite its simplicity and low cost, the CDT offers valuable insights into cognitive status. However, there are considerations regarding education and ethnicity in interpreting CDT results, with evidence suggesting that factors such as reading ability may influence performance more than years of education or ethnicity. There\'s also ongoing research to enhance the sensitivity of the CDT, especially in detecting early cognitive changes associated with conditions like MCI and AD. While normative data on CDT performance is limited, recent studies aim to provide more comprehensive and expanded scoring systems to better capture subtle cognitive differences, especially in preclinical stages of dementia.","sidebar":"docsMainSidebar"},"fhsdata/legacy_data/parkinsons_disease":{"id":"fhsdata/legacy_data/parkinsons_disease","title":"Parkinson\'s Disease","description":"The Framingham Parkinson\u2019s Disease Epidemiology study has tracked incident cases of Parkinson\u2019s disease across all Framingham cohorts. Those found to identify Parkinson\u2019s disease by self-report or by medical history update are brought to a diagnostic consensus meeting to determine if Parkinson\u2019s disease or a related disorder is evident. PD review is the process used at FHS to adjudicate diagnoses of Parkinsonism and PD cases. A list of participants flagged for possibly having signs of PD or parkinsonism is generated and participants for review are identified. For each participant, a PD Review Case Summary (PDRCS), a summary of what is known about a participant, is prepared by a trained research assistant, including relevant medical history, education, and exam results. The summary is compiled using several FHS and external sources of information. The PDRCS is brought to a PD Review meeting, which includes an adjudication panel with movement disorder neurologists present. The panel evaluates each PDRCS to identify whether there is evidence of PD. Medical history and family history are also recorded. During the PD Review meeting, the PD Review data is entered directly into a REDCap project database. The neurologists in attendance view the data entry to ensure accuracy.","sidebar":"docsMainSidebar"},"fhsdata/legacy_data/qualitative_errors_in_neuropsychological_exams":{"id":"fhsdata/legacy_data/qualitative_errors_in_neuropsychological_exams","title":"Qualitative Errors in Neuropsychological Exams","description":"1. This dataset contains measurements related to Boston Process Approach (BPA) Errors","sidebar":"docsMainSidebar"},"fhsdata/legacy_data/traumatic_brain_injury_retrospective_chart_review":{"id":"fhsdata/legacy_data/traumatic_brain_injury_retrospective_chart_review","title":"Traumatic Brain Injury Retrospective Chart Review","description":"Traumatic Brain Injury (TBI) and spinal cord injuries are the leading causes of death among","sidebar":"docsMainSidebar"},"fhsdata/neuropsychological_testing":{"id":"fhsdata/neuropsychological_testing","title":"Neuropsychological testing","description":"Neuropsychological testing data. This page combines variable and description information from all three curated datasets."},"intro":{"id":"intro","title":"Introduction","description":"The above presentation is an introduction to Framingham Heart Study data. It is intended for new analysts with access to FHS data to view as part of their training, but is also available as a public introduction. It allows new analysts to gain knowledge about the FHS and learn the common terminology quickly during the brief presentation. The presentation covers general information about the FHS cohorts and their participants. The types of data the FHS uses, their collection, and their documentation are introduced. The methods of FHS file storage, access, and security for analysts are explained, including the FHS database (FRAM-DATA) and the BU Shared Computing Cluster (SCC).","sidebar":"docsMainSidebar"},"resources/fhs_data_bio_specimen_request":{"id":"resources/fhs_data_bio_specimen_request","title":"FHS Data/Biospecimen Request","description":"FHS Data/Biospecimen Request"},"resources/fhs_health_exam_timeline":{"id":"resources/fhs_health_exam_timeline","title":"Cohort Study Designs","description":"Figure 1-2. The age distribution of FHS participants at each health exam (core exam) across all six cohorts Unlike the other three generations, Omni 1 and Omni 2 were independent and have no generational relations.","sidebar":"docsMainSidebar"},"resources/general_data_types":{"id":"resources/general_data_types","title":"General Data Types","description":"Currently, FHS has more than 600 conventional datasets that contain data collected from both the FHS core study and various ancillary studies. These datasets range from simple demographic and self-reporting data points to more complex multi-omic and digital data. In addition to these structured data, FHS has also been gathering unstructured data, especially in the recent years.","sidebar":"docsMainSidebar"},"useful_links":{"id":"useful_links","title":"Useful Links","description":"\ud83d\udcc2 Useful Links - Background Information"},"variables/alcohol_consumption":{"id":"variables/alcohol_consumption","title":"Alcohol Consumption","description":"Measures of alcohol consumption. This page combines variable and description information from the Gen 2/Omni 1 and and Gen 3/Omni 2/NOS curated datasets."},"variables/anthropometric_measurements":{"id":"variables/anthropometric_measurements","title":"Anthropometric Measurements","description":"Basic physical measurements of the body. This page combines variable and description information from all three curated datasets."},"variables/blood_glucose":{"id":"variables/blood_glucose","title":"Blood Glucose, Diabetes and Treatment","description":"Measures of blood glucose metrics, and diabetes metrics and treatment. This page combines variable and description information from all three curated datasets."},"variables/blood_pressures":{"id":"variables/blood_pressures","title":"Blood Pressures, Heart Rate, Ventricular Hypertrophy and Antihypertensives","description":"Metrics of blood pressure, heart rate, ventricular hypertrophy presence and antihypertensive intake. This page combines variable and description information from all three curated datasets."},"variables/cesd":{"id":"variables/cesd","title":"Center for Epidemiologic Studies Depression Scale (CES-D)","description":"Scores of CES-D questionnaire, used to test for depression. Data from core exam. This page combines variable and description information from the Gen 2/Omni 1 and and Gen 3/Omni 2/NOS curated datasets."},"variables/creatinine":{"id":"variables/creatinine","title":"Creatinine","description":"Serum creatinine measure. This page combines variable and description information from all three curated datasets."},"variables/demographics":{"id":"variables/demographics","title":"Demographics","description":"Basic demographic information including ID, core exam date, age, sex, race and education. This page combines variable and description information from all three curated datasets."},"variables/fhs_cvd":{"id":"variables/fhs_cvd","title":"FHS CVD Risk Score","description":"FHS CVD risk score and component scores. All of the variables in this section are derived from other variables in the curated dataset. This page combines variable and description information from all three curated datasets."},"variables/fhs_stroke":{"id":"variables/fhs_stroke","title":"FHS Stroke Risk Profile","description":"FHS stroke risk profile and component scores. All of the variables in this section are derived from other variables in the curated dataset. This page combines variable and description information from all three curated datasets."},"variables/lipid_panel":{"id":"variables/lipid_panel","title":"Lipid Panel and Hyperlipidemia","description":"Cholesterol measurements and information about related treatment. This page combines variable and description information from all three curated datasets."},"variables/matching_np_dates":{"id":"variables/matching_np_dates","title":"Matching NP Dates with Core Exam Dates","description":"Core exams and NP exams are not synchronized and take place on different days and cycles. These variables help to match the exam dates. This page combines variable and description information from all three curated datasets."},"variables/mmse":{"id":"variables/mmse","title":"Mini-Mental State Examination (MMSE)","description":"Scores of MMSE questionnaire, used to test for cognitive impairment. This page combines variable and description information from the Gen 1 and Gen 2/Omni 1 curated datasets."},"variables/new_variables_page":{"id":"variables/new_variables_page","title":"Variables","description":"The following variable pages are organized by research domain categories as they are in the curated datasets, where they are all available for the exams where they were collected. The curated datasets contain detailed records of variables from participant exams and tests collected over multiple core and neuropsychological (NP) exam cycles.","sidebar":"docsMainSidebar"},"variables/prevalence":{"id":"variables/prevalence","title":"Prevalence","description":"History of certain conditions present at core and NP exams. All of the variables in this section are derived from other variables in the curated dataset. This page combines variable and description information from all three curated datasets."},"variables/smoking":{"id":"variables/smoking","title":"Smoking","description":"Smoking status. This page combines variable and description information from all three curated datasets."},"variables/survival_information":{"id":"variables/survival_information","title":"Survival Information","description":"Dates of last documented contact and death of participant. This page combines variable and description information from all three curated datasets."},"variables/verified_af":{"id":"variables/verified_af","title":"Verified Outcomes \u2013 First Atrial Fibrillation (AF) Event","description":"Documented date of first atrial fibrillation (AF) event. This page combines variable and description information from all three curated datasets."},"variables/verified_cancer":{"id":"variables/verified_cancer","title":"Verified Outcomes \u2013 First Cancer and Related Variables","description":"Documented dates and other information related to first cancer event. This page combines variable and description information from all three curated datasets."},"variables/verified_chd":{"id":"variables/verified_chd","title":"Verified Outcomes \u2013 First Coronary Heart Disease (CHD) Event","description":"Documented date of first coronary heart disease (CHD) event. This page combines variable and description information from all three curated datasets."},"variables/verified_cva":{"id":"variables/verified_cva","title":"Verified Outcomes \u2013 First Stroke (CVA) Event","description":"Documented date of first stroke (CVA) event. This page combines variable and description information from all three curated datasets."}}}}')}}]);